import { Component, OnInit } from '@angular/core';
import {NavController} from '@ionic/angular'
import {ActivatedRoute,Router,ParamMap} from '@angular/router';
import { AlertController } from '@ionic/angular';

@Component({
  selector: 'app-choices',
  templateUrl: './choices.page.html',
  styleUrls: ['./choices.page.scss'],
})
export class ChoicesPage implements OnInit {

  constructor(private navCtrl:NavController,private router:Router,private alertCtrl:AlertController,private route:ActivatedRoute) {
   }
   ngOnInit() {
   };

  async logout(){
    const alert = await this.alertCtrl.create({
      header: 'Confirm!',
      message: '<strong>Do you want to Logout !</strong>',
      buttons: [
        {
          text: 'No',
          role: 'cancel',
          cssClass: 'secondary',
          handler: (blah) => {
            console.log('Confirm Cancel: blah');
          }
        }, {
          text: 'Yes',
          handler: () => {
            localStorage.clear();
    this.navCtrl.navigateBack('/login');
          }
        }
      ]
    });

    await alert.present();
  }
  btnclick(){
    this.navCtrl.navigateBack('/changepassword');
  }
}
